def reward(context, completion):
    # Define some weights to balance the importance of different factors
    relevance_weight = 0.4
    coherence_weight = 0.3
    specificity_weight = 0.2
    helpfulness_weight = 0.1

    # Initialize the reward score
    reward_score = 0

    # Function to evaluate relevance: Higher if completion directly addresses the context
    def evaluate_relevance(context, completion):
        if 'Answer not directly related to the context' in completion:
            return 0
        elif 'Directly answers the context' in completion:
            return 10000
        return 0

    # Function to evaluate coherence: Higher if the completion is logically consistent
    def evaluate_coherence(context, completion):
        if 'Completion is logically inconsistent' in completion:
            return 0
        elif 'Completion is logically consistent' in completion:
            return 10000
        return 0

    # Function to evaluate specificity: Higher if the completion provides detailed information
    def evaluate_specificity(context, completion):
        if 'Completion is vague' in completion:
            return 0
        elif 'Completion is specific' in completion:
            return 10000
        return 0

    # Function to evaluate helpfulness: Higher if the completion is useful to the user
    def evaluate_helpfulness(context, completion):
        if 'Completion is not helpful' in completion:
            return 0
        elif 'Completion is helpful' in completion:
            return 10000
        return 0

    # Calculate the weighted sum of the evaluation scores
    reward_score += relevance_weight * evaluate_relevance(context, completion)
    reward_score += coherence_weight * evaluate_coherence(context, completion)
    reward_score += specificity_weight * evaluate_specificity(context, completion)
    reward_score += helpfulness_weight * evaluate_helpfulness(context, completion)

    # Ensure the reward score is within the specified range
    return max(-100000, min(100000, reward_score))
```

